import SideDrawerApp from './SideDrawerApp.vue';
import '../../界面/状态栏/global.css';
import { backfillNpcPanelsIfEmpty } from '../../util/npcPanelSync';
import { dispatch_drawer_open, ensure_float_logo, hide_float_logo, hide_modal_iframe, register_float_logo_bridge, reposition_float_logo_on_resize, show_float_logo, show_modal_iframe, } from './floatLogo';
import { DRAWER_CHAT_ATTR, DRAWER_HOST_ATTR, is_drawer_iframe_expanded, repair_drawer_iframe_layout, } from '../../界面/状态栏/util/sideDrawerHost';
import { teleportStyle } from '@util/script';
import drawer_srcdoc from '@util/drawer_iframe_srcdoc.html';
const REMOUNT_DEBOUNCE_MS = 300;
let destroy_mount;
let booting = false;
let remount_timer;
let watch_bound = false;
function tavern_window() {
    try {
        if (window.parent && window.parent !== window) {
            return window.parent;
        }
    }
    catch {
        /* cross-origin */
    }
    return window;
}
function tavern_document() {
    return tavern_window().document;
}
function $drawer_iframe() {
    return $(`iframe[${DRAWER_HOST_ATTR}]`, tavern_document());
}
function get_current_chat_id() {
    return SillyTavern.getCurrentChatId?.() ?? '';
}
function create_drawer_iframe() {
    return $('<iframe>').attr({
        [DRAWER_HOST_ATTR]: '',
        frameborder: '0',
        srcdoc: drawer_srcdoc,
    });
}
function ensure_drawer_iframe_shell() {
    let $iframe = $drawer_iframe();
    if ($iframe.length === 0) {
        $iframe = create_drawer_iframe()
            .attr(DRAWER_CHAT_ATTR, get_current_chat_id())
            .css({
            position: 'fixed',
            top: '0',
            left: '0',
            width: `${tavern_window().innerWidth}px`,
            height: `${tavern_window().innerHeight}px`,
            border: '0',
            zIndex: '10050',
            background: 'transparent',
            pointerEvents: 'none',
            display: 'none',
        })
            .appendTo($(tavern_document().body));
    }
    return $iframe;
}
function is_drawer_ready() {
    const win = $drawer_iframe()[0]?.contentWindow;
    return typeof win?.__zhuixing_drawer?.open === 'function' || is_drawer_iframe_expanded();
}
function is_drawer_mounted() {
    const iframe = $drawer_iframe()[0];
    if (!iframe?.isConnected) {
        return false;
    }
    const app_root = iframe.contentDocument?.querySelector('#app[data-mounted]');
    return Boolean(app_root && app_root.childElementCount > 0);
}
function repair_drawer_iframe_width() {
    repair_drawer_iframe_layout();
}
function reset_drawer_vue_mount() {
    destroy_mount?.();
    destroy_mount = undefined;
    const doc = $drawer_iframe()[0]?.contentDocument;
    doc?.querySelector('#app')?.remove();
}
async function wait_ms(ms) {
    await new Promise(resolve => {
        setTimeout(resolve, ms);
    });
}
async function open_status_panel() {
    await ensure_side_drawer();
    hide_float_logo();
    show_modal_iframe();
    for (let attempt = 0; attempt < 30; attempt += 1) {
        dispatch_drawer_open();
        $drawer_iframe()[0]?.contentWindow?.__zhuixing_drawer?.open();
        if (is_drawer_iframe_expanded()) {
            return;
        }
        await wait_ms(50);
    }
    console.warn('[状态栏侧栏] 打开状态栏失败，已恢复坠星按钮');
    hide_modal_iframe();
    show_float_logo();
}
function mount_side_drawer() {
    const $iframe = ensure_drawer_iframe_shell();
    $iframe.attr(DRAWER_CHAT_ATTR, get_current_chat_id());
    let app;
    let style_teleport;
    const mount_app = () => {
        const doc = $iframe[0]?.contentDocument;
        if (!doc || is_drawer_mounted()) {
            repair_drawer_iframe_width();
            return;
        }
        app?.unmount();
        style_teleport?.destroy();
        doc.querySelector('#app')?.remove();
        style_teleport = teleportStyle(doc.head);
        const $mount = $('<div id="app" data-mounted="">').appendTo(doc.body);
        app = createApp(SideDrawerApp).use(createPinia());
        errorCatched(() => {
            app.mount($mount[0]);
            console.info('[状态栏侧栏] 已挂载');
            repair_drawer_iframe_width();
        })();
    };
    $iframe.off('load').one('load', mount_app);
    mount_app();
    return () => {
        app?.unmount();
        app = undefined;
        style_teleport?.destroy();
        style_teleport = undefined;
    };
}
function cleanup_stale_parent_modal_host() {
    try {
        window.parent?.document?.getElementById('zhuixing-modal-host')?.remove();
    }
    catch {
        // 父页面不可访问时忽略
    }
}
async function boot_side_drawer(force_remount = false) {
    if (typeof getVariables !== 'function') {
        console.warn('[状态栏侧栏] 非酒馆环境，跳过挂载');
        return;
    }
    if (booting) {
        return;
    }
    if (!force_remount && is_drawer_mounted()) {
        repair_drawer_iframe_width();
        return;
    }
    booting = true;
    try {
        cleanup_stale_parent_modal_host();
        await waitGlobalInitialized('Mvu');
        await errorCatched(backfillNpcPanelsIfEmpty)();
        if (force_remount) {
            reset_drawer_vue_mount();
        }
        destroy_mount?.();
        destroy_mount = mount_side_drawer();
    }
    catch (error) {
        console.error('[状态栏侧栏] 挂载失败', error);
    }
    finally {
        booting = false;
    }
}
async function ensure_side_drawer() {
    if (typeof getVariables !== 'function') {
        return;
    }
    ensure_drawer_iframe_shell();
    const iframe = $drawer_iframe()[0];
    const chat_id = get_current_chat_id();
    const prev_chat = iframe?.getAttribute(DRAWER_CHAT_ATTR) ?? '';
    const chat_changed = Boolean(chat_id && prev_chat && prev_chat !== chat_id);
    if (chat_changed) {
        reset_drawer_vue_mount();
    }
    if (iframe && chat_id) {
        iframe.setAttribute(DRAWER_CHAT_ATTR, chat_id);
    }
    const stale_mount = is_drawer_mounted() && !is_drawer_ready();
    if (chat_changed || !is_drawer_mounted() || stale_mount) {
        await boot_side_drawer(chat_changed || stale_mount);
    }
    else {
        repair_drawer_iframe_width();
    }
}
function schedule_ensure_drawer() {
    if (remount_timer) {
        clearTimeout(remount_timer);
    }
    remount_timer = setTimeout(() => {
        remount_timer = undefined;
        void ensure_side_drawer();
    }, REMOUNT_DEBOUNCE_MS);
}
function watch_side_drawer() {
    if (watch_bound) {
        return;
    }
    watch_bound = true;
    let layout_resize_timer;
    const schedule_layout_repair = () => {
        if (layout_resize_timer) {
            clearTimeout(layout_resize_timer);
        }
        layout_resize_timer = setTimeout(() => {
            layout_resize_timer = undefined;
            repair_drawer_iframe_layout();
            reposition_float_logo_on_resize();
        }, 150);
    };
    $(tavern_window()).on('resize orientationchange', schedule_layout_repair);
    eventOn(tavern_events.CHAT_CHANGED, () => {
        schedule_ensure_drawer();
    });
    eventOn(tavern_events.APP_READY, () => {
        schedule_ensure_drawer();
    });
}
$(async () => {
    register_float_logo_bridge();
    ensure_float_logo(() => {
        void open_status_panel();
    });
    hide_modal_iframe();
    await ensure_side_drawer();
    if (!is_drawer_ready()) {
        await boot_side_drawer(true);
    }
    watch_side_drawer();
});
