export async function apply_wreck_opening_preset_to_mvu(): Promise<void> {
  await waitGlobalInitialized('Mvu');
  markStatusBarLocalMutation(15000);

  const store = useDataStore();
  const next = Schema.parse(build_wreck_opening_stat(Schema.parse(store.data)));

  const message_id = resolve_latest_message_id();
  if (message_id === null) {
    Object.assign(store.data, next);
    console.warn('[迫降定稿] 无聊天楼层，仅写入本地 store');
    return;
  }

  const option = { type: 'message' as const, message_id };
  const mvu_data = Mvu.getMvuData(option) ?? {};
  _.set(mvu_data, 'stat_data', next);
  await Mvu.replaceMvuData(mvu_data, option);

  Object.assign(store.data, next);
  console.info('[迫降定稿] 已预置开场结束 stat_data 到楼层', message_id);
}

function wreck_opening_stat_needs_repair(stat_data: Record<string, unknown>): boolean {
  const npc_count = _.keys(_.get(stat_data, '具名NPC', {})).length;
  const warehouse = _.get(stat_data, '营地.仓库储备', {}) as Record<string, { 当前?: number }>;
  const has_opening_food =
    Number(warehouse.高蛋白棒?.当前) > 0 ||
    Number(warehouse.压缩饼干?.当前) > 0 ||
    Number(warehouse.营养肉罐头?.当前) > 0;
  return npc_count < 4 || !has_opening_food;
}

/** 定稿开场已写入但 stat 未就绪时，重新解析楼层内 UpdateVariable（旧存档兜底） */
export async function ensure_wreck_opening_stat_if_needed(): Promise<void> {
  if (typeof getChatMessages !== 'function' || typeof getVariables !== 'function') {
    return;
  }
  const latest = getChatMessages(-1, { role: 'assistant' })[0];
  if (!latest?.message.includes(WRECK_FIXED_OPENING_MARKER)) {
    return;
  }
  const stat_data = _.get(getVariables({ type: 'message', message_id: 'latest' }), 'stat_data', {}) as Record<
    string,
    unknown
  >;
  if (!wreck_opening_stat_needs_repair(stat_data)) {
    return;
  }
  console.info('[迫降定稿] 检测到定稿开场但变量未就绪，正在解析 UpdateVariable');
  const applied = await apply_wreck_opening_variables_from_message(latest.message_id, latest.message);
  const after = _.get(getVariables({ type: 'message', message_id: 'latest' }), 'stat_data', {}) as Record<
    string,
    unknown
  >;
  if (!applied || wreck_opening_stat_needs_repair(after)) {
    await apply_wreck_opening_preset_to_mvu();
  }
}
