import gsap from 'gsap';

export const DRAWER_HOST_ATTR = 'data-zhuixing-side-drawer';
export const DRAWER_CHAT_ATTR = 'data-zhuixing-chat-id';
export const DRAWER_OPEN_EVENT = 'zhuixing-open-drawer';
export const DRAWER_CLOSE_EVENT = 'zhuixing-close-drawer';
export const DRAWER_LOGO_PX = 52;
export const DRAWER_EXPANDED_WIDTH = 'min(680px, calc(100vw - 24px))';
export const DRAWER_EXPANDED_PX = 680;

export type DrawerIframeLayout = {
  open: boolean;
  logo_x: number;
  logo_y: number;
  logo_size?: number;
};

function resolve_viewport_width(): number {
  try {
    if (window.parent && window.parent !== window) {
      return window.parent.innerWidth;
    }
  } catch {
    /* cross-origin */
  }
  return window.innerWidth;
}

function resolve_viewport_height(): number {
  try {
    if (window.parent && window.parent !== window) {
      return window.parent.innerHeight;
    }
  } catch {
    /* cross-origin */
  }
  return window.innerHeight;
}

function resolve_logo_size(): number {
  const vw = resolve_viewport_width();
  return vw <= 480 ? 48 : DRAWER_LOGO_PX;
}

function find_drawer_iframe(): HTMLIFrameElement | null {
  const candidates: (HTMLIFrameElement | null | undefined)[] = [];
  try {
    const frame = window.frameElement as HTMLIFrameElement | null;
    if (frame?.hasAttribute(DRAWER_HOST_ATTR)) {
      candidates.push(frame);
    }
  } catch {
    /* ignore */
  }
  try {
    candidates.push(
      window.parent.document.querySelector(`iframe[${DRAWER_HOST_ATTR}]`) as HTMLIFrameElement | null,
    );
  } catch {
    /* ignore */
  }
  return candidates.find(Boolean) ?? null;
}

export function is_drawer_iframe_expanded(): boolean {
  const iframe = find_drawer_iframe();
  return Boolean(iframe?.contentDocument?.querySelector('.side-drawer-root.is-expanded'));
}

function sync_drawer_host_viewport_tier(iframe: HTMLIFrameElement): void {
  const doc = iframe.contentDocument;
  if (!doc) {
    return;
  }
  const vw = resolve_viewport_width();
  const tier = vw <= 480 ? 'phone' : vw <= 900 ? 'tablet' : 'desktop';
  doc.documentElement.dataset.drawerViewportTier = tier;
}

function apply_drawer_iframe_layout(iframe: HTMLIFrameElement, layout: DrawerIframeLayout): void {
  iframe.style.right = 'auto';
  iframe.style.border = '0';
  iframe.style.background = 'transparent';
  iframe.style.zIndex = '10050';
  void layout.logo_size;

  if (layout.open) {
    iframe.style.display = 'block';
    iframe.style.pointerEvents = 'auto';
    iframe.style.top = '0';
    iframe.style.left = '0';
    iframe.style.width = `${resolve_viewport_width()}px`;
    iframe.style.height = `${resolve_viewport_height()}px`;
  } else {
    iframe.style.display = 'none';
    iframe.style.pointerEvents = 'none';
  }

  sync_drawer_host_viewport_tier(iframe);
}

let last_layout: DrawerIframeLayout = { open: false, logo_x: 0, logo_y: 0 };

export function sync_drawer_iframe_layout(
  openOrLayout?: boolean | DrawerIframeLayout,
  logo_x = 0,
  logo_y = 0,
): void {
  const iframe = find_drawer_iframe();
  if (!iframe) {
    return;
  }

  let layout: DrawerIframeLayout;
  if (typeof openOrLayout === 'object') {
    layout = openOrLayout;
  } else {
    layout = {
      open: Boolean(openOrLayout),
      logo_x,
      logo_y,
      logo_size: resolve_logo_size(),
    };
  }

  last_layout = layout;
  apply_drawer_iframe_layout(iframe, layout);
}

export function sync_drawer_iframe_width(open: boolean, animate = true): void {
  sync_drawer_iframe_layout({ ...last_layout, open, logo_size: resolve_logo_size() });
  void animate;
}

export function sync_drawer_iframe_width_px(_width_px: number, animate = true): void {
  sync_drawer_iframe_layout({ ...last_layout, logo_size: resolve_logo_size() });
  void animate;
}

export function repair_drawer_iframe_layout(): void {
  sync_drawer_iframe_layout(is_drawer_iframe_expanded() ? { ...last_layout, open: true } : last_layout);
}

export function resolve_drawer_logo_size(): number {
  return resolve_logo_size();
}
